test("crews scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  await ui.setSetting(pg_uma, "pot", "7.77");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-10", "half-even")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00", "from": "2026-03-10", "to": "2026-03-25"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "60.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "40.00"})).toBe(true);
  expect(await ui.addPool(pg_uma, "P2")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P2", {"member": "Ben", "share": "100.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "pool:P2", "share": "10.00"})).toBe(true);
  expect(await ui.addCrew(pg_uma, "C1", "Ben")).toBe(true);
  expect(await ui.addCrewMember(pg_uma, "C1", "Ada")).toBe(true);
  expect(await ui.bulkGrade(pg_uma, [p_ada, p_ben], {"grade": "A"})).toBe(2);
  expect(await ui.watch(pg_uma, p_ada, true)).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50", "from": "2026-03-01", "to": "2026-03-25"})).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ben, "Ada")).toBe(true);
